def pair11_predecessor(base, binding, actual, owner):
    base.need(same_json(binding.get('pair11_transition'), PAIR11_TRANSITION), 'Pair11 transition differs')
    base.need(len(actual) == 113 and owner.source_digest(actual) == PAIR11_TRANSITION['sourceAfter'], 'Pair11 current source differs')
    base.need(same_json(PAIR12_TRANSITION['profileBefore'], PAIR11_TRANSITION['profileAfter']), 'Pair11 exact profile differs')
    predecessor = dict(actual)
    for row in PAIR11_TRANSITION['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair11 current owning row differs')
        predecessor[row['path']] = row['before']
    base.need(owner.source_digest(predecessor) == PAIR11_TRANSITION['sourceBefore'], 'Pair11 predecessor source differs')
    return predecessor

def pair11_predecessor_raw(base, path):
    raw = pair12_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR11_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} == row['after'], 'Pair11 exact raw successor differs')
    old = raw.replace(PAIR11_TRANSITION['profileAfter']['id'].encode(), PAIR11_TRANSITION['profileBefore']['id'].encode())
    base.need({'bytes':len(old),'sha256':hashlib.sha256(old).hexdigest()} == row['before'], 'Pair11 exact raw predecessor differs')
    return old


