def pair12_predecessor(base, binding, actual, owner):
    transition = PAIR12_TRANSITION
    base.need(same_json(binding.get('pair12_transition'), transition), 'Pair12 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair12 current source differs')
    base.need(same_json(PAIR13_TRANSITION['profileBefore'], transition['profileAfter']), 'Pair12 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair12 current owning row differs')
        if row['before'] is None:
            del predecessor[row['path']]
        else:
            predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair12 predecessor source differs')
    return predecessor

def pair12_predecessor_raw(base, path):
    raw = pair13_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR12_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} == row['after'], 'Pair12 exact raw successor differs')
    old = raw.decode()
    for edit in reversed(row['edits']):
        old = old.replace(edit['after'], edit['before'])
    old = old.encode()
