def pair14_predecessor(base, binding, actual, owner):
    transition = PAIR14_TRANSITION
    base.need(same_json(binding.get('pair14_transition'), transition), 'Pair14 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair14 current source differs')
    base.need(same_json(PAIR15_TRANSITION['profileBefore'], transition['profileAfter']), 'Pair14 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair14 current owning row differs')
        predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair14 predecessor source differs')
    return predecessor

def pair14_predecessor_raw(base, path):
    raw = pair15_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR14_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} == row['after'], 'Pair14 exact raw successor differs')
    old = raw.decode()
    for edit in reversed(row['edits']):
        old = old.replace(edit['after'], edit['before'])
    old = old.encode()
    base.need({'bytes':len(old),'sha256':hashlib.sha256(old).hexdigest()} == row['before'], 'Pair14 exact raw predecessor differs')
