def pair15_predecessor(base, binding, actual, owner):
    transition = PAIR15_TRANSITION
    base.need(same_json(binding.get('pair15_transition'), transition), 'Pair15 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair15 current source differs')
    base.need(same_json(PAIR16_TRANSITION['profileBefore'], transition['profileAfter']), 'Pair15 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair15 current owning row differs')
        if row['before'] is None:
            del predecessor[row['path']]
        else:
            predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair15 predecessor source differs')
    return predecessor

def pair15_predecessor_raw(base, path):
    raw = pair16_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR15_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} == row['after'], 'Pair15 exact raw successor differs')
    old = raw.decode()
    for edit in reversed(row['edits']):
        old = old.replace(edit['after'], edit['before'])
    old = old.encode()
    base.need({'bytes':len(old),'sha256':hashlib.sha256(old).hexdigest()} == row['before'], 'Pair15 exact raw predecessor differs')
    return old


