def pair18_predecessor(base, binding, actual, owner):
    transition = PAIR18_TRANSITION
    base.need(same_json(binding.get('pair18_transition'), transition), 'Pair18 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair18 current source differs')
    base.need(same_json(PAIR19_TRANSITION['profileBefore'], transition['profileAfter']), 'Pair18 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair18 current owning row differs')
        predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair18 predecessor source differs')
    return predecessor

def pair18_predecessor_raw(base, path):
    raw = pair19_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR18_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} == row['after'], 'Pair18 exact raw successor differs')
    old = raw.decode()
    for edit in reversed(row['edits']):
        old = old.replace(edit['after'], edit['before'])
    old = old.encode()
    base.need({'bytes':len(old),'sha256':hashlib.sha256(old).hexdigest()} == row['before'], 'Pair18 exact raw predecessor differs')
    return old


