def pair20_predecessor(base, binding, actual, owner):
    transition = PAIR20_TRANSITION
    base.need(same_json(binding.get('pair20_transition'), transition), 'Pair20 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair20 current source differs')
    base.need(same_json(owner.load_profile(ROOT), transition['profileAfter']), 'Pair20 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair20 owning row differs')
        predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair20 predecessor differs')
    return predecessor

def pair20_predecessor_raw(base, path):
    raw = base.regular(path).read_bytes()
    relative = path.relative_to(ROOT).as_posix()
    row = next((r for r in PAIR20_TRANSITION['rawPredecessors'] if r['path'] == relative), None)
    if row is None:
        return raw
    base.need(same_json({'bytes':len(raw), 'sha256':hashlib.sha256(raw).hexdigest()}, row['after']), 'Pair20 exact raw successor differs')
    lines = raw.decode().splitlines(True)
    for edit in reversed(row['reverseEdits']):
        lines[edit['afterStartLine']:edit['afterEndLine']] = [edit['beforeText']]
    old = ''.join(lines).encode()
    base.need(same_json({'bytes':len(old), 'sha256':hashlib.sha256(old).hexdigest()}, row['before']), 'Pair20 exact raw predecessor differs')
    return old

def guest_ui_v2_predecessor(base, binding, actual, owner):
    transition = GUEST_UI_V2_TRANSITION
    base.need(same_json(binding.get('guest_ui_v2_transition'), transition), 'Guest UI V2 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Guest UI V2 current source differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Guest UI V2 owning row differs')
        if row['before'] is None:
            del predecessor[row['path']]
        else:
            predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Guest UI V2 predecessor differs')
    return predecessor

def guest_ui_v2_predecessor_raw(base, path):
    raw = pair20_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next((r for r in GUEST_UI_V2_TRANSITION['rawPredecessors'] if r['path'] == relative), None)
    if row is None:
        return raw
