def pair19_predecessor(base, binding, actual, owner):
    receipt = PAIR19_RECEIPT_TRANSITION
    base.need(same_json(binding.get('pair19_receipt_transition'), receipt), 'Pair19 receipt typed transition differs')
    base.need(len(actual) == receipt['sourceCount'] and owner.source_digest(actual) == receipt['sourceAfter']
              and same_json(actual.get(receipt['path']), receipt['after']), 'Pair19 receipt current source differs')
    actual = dict(actual)
    actual[receipt['path']] = receipt['before']
    base.need(owner.source_digest(actual) == receipt['sourceBefore'], 'Pair19 receipt predecessor source differs')
    transition = PAIR19_TRANSITION
    base.need(same_json(binding.get('pair19_transition'), transition), 'Pair19 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair19 current source differs')
    base.need(same_json(PAIR20_TRANSITION['profileBefore'], transition['profileAfter']), 'Pair19 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair19 current owning row differs')
        if row['before'] is None:
            del predecessor[row['path']]
        else:
            predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair19 predecessor source differs')
    return predecessor

def pair19_predecessor_raw(base, path):
    raw = pair20_predecessor_raw(base, path)
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR19_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need(same_json({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}, row['after']), 'Pair19 exact raw successor differs')
    old = raw.decode()
    for edit in reversed(row['edits']):
        old = old.replace(edit['after'], edit['before'])
    old = old.encode()
    base.need(same_json({'bytes':len(old),'sha256':hashlib.sha256(old).hexdigest()}, row['before']), 'Pair19 exact raw predecessor differs')
    return old


